def countTriplets(nums):
    from collections import Counter

    # Count all possible nums[i] & nums[j] results
    ab_count = Counter()
    for a in nums:
        for b in nums:
            ab_count[a & b] += 1

    total = 0
    # For each c, sum over all (a & b) pairs compatible with c
    for c in nums:
        for ab, cnt in ab_count.items():
            if ab & c == 0:
                total += cnt
    return total
